CREATE OR REPLACE FUNCTION public.update_available_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
                                    DECLARE
                                      total_used NUMERIC;
                                        card_limit NUMERIC;
                                          card_id UUID;
                                          BEGIN
                                            -- Pegar o ID do cartão (do INSERT ou do DELETE)
                                              card_id := COALESCE(NEW.credit_card_id, OLD.credit_card_id);

                                                -- Se não há cartão vinculado, apenas retorna sem fazer nada
                                                  IF card_id IS NULL THEN
                                                      RETURN COALESCE(NEW, OLD);
                                                        END IF;

                                                          -- Somar todas as transações do cartão
                                                            SELECT COALESCE(SUM(CASE WHEN type = 'income' THEN -amount ELSE amount END), 0)
                                                                INTO total_used
                                                                    FROM transactions
                                                                        WHERE credit_card_id = card_id
                                                                              AND user_id = COALESCE(NEW.user_id, OLD.user_id);

                                                                                -- Buscar limite total do cartão
                                                                                  SELECT limit_amount INTO card_limit
                                                                                      FROM credit_cards
                                                                                          WHERE id = card_id;

                                                                                            -- Atualizar available_limit se o cartão existir
                                                                                              IF card_limit IS NOT NULL THEN
                                                                                                  UPDATE credit_cards
                                                                                                        SET available_limit = card_limit - total_used
                                                                                                              WHERE id = card_id;
                                                                                                                END IF;

                                                                                                                  RETURN COALESCE(NEW, OLD);
                                                                                                                  END;
                                                                                                                  $function$
